<?php
require dirname(__DIR__) . '/app/bootstrap.php'; require_role('Head Administrator');
$rows=db()->query("SELECT s.student_number,s.first_name,s.last_name,s.email,s.student_status,d.department_name FROM students s LEFT JOIN departments d ON d.department_id=s.department_id ORDER BY s.last_name,s.first_name LIMIT 500")->fetchAll();
require dirname(__DIR__).'/app/layout.php'; page_header('Students'); ?>
<section class="page-title"><div><h1>Student Management</h1><p>Registered student accounts.</p></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Student number</th><th>Name</th><th>Email</th><th>Department</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['student_number']) ?></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['department_name']) ?></td><td><?= e($r['student_status']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">No students have been registered yet. Student registration/import screen is the next module to add.</td></tr><?php endif; ?></tbody></table></div></section><?php page_footer(); ?>
